head.script:
// https://inswave01.atlassian.net/browse/WAEA-1200
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// useXHR "true" , timeout 1 로 대기 시간을 초과시켜 콜백 실행 횟수를 세어 출력
//  · 호출 시 전달한 객체에 엔진이 내부 값을 덧붙이므로 출력 문자열은 호출 전에 만들어 둔다.
//  · 콜백은 비동기로 실행되므로 일정 시간 뒤에 누적된 횟수를 출력한다.
scwin.btn_xhr_onclick = function () {
    var arrSuccess = [];
    var arrFailure = [];
    var nStart = new Date().getTime();

    var strShow = "useXHR \"true\" , timeout 1";

    target1.advancedExcelDownload({
        "useXHR" : "true",
        "timeout" : 1,
        "onSuccessCallback" : function () { arrSuccess.push(new Date().getTime() - nStart); },
        "onFailureCallback" : function () { arrFailure.push(new Date().getTime() - nStart); }
    });

    setTimeout(function () {
        scwin.setReturnValue(strShow);
        scwin.setReturnValue("onSuccessCallback 실행 횟수 : " + arrSuccess.length);
        scwin.setReturnValue("onFailureCallback 실행 횟수 : " + arrFailure.length + (arrFailure.length > 0 ? "  (실행 시점 ms : " + arrFailure.join(" , ") + ")" : ""));
        scwin.setReturnValue("");
    }, 5000);
};
